for p in pathlib.Path('.').rglob('*'):
 if not p.is_file() or '.git' in p.parts:continue
 try:s=p.read_text()
 except:continue
 for kind,pat in patterns:
  for m in re.finditer(pat,s):print(kind,str(p),s.count('\\n',0,m.start())+1,'length',len(m.group()))
 # High entropy strings, excluding hex digests and embedded data fixtures.
 if p.suffix in ['.py','.yaml','.yml','.md','.toml','.sh','.txt']:
  for m in re.finditer(r'[\\\"\\x27]([A-Za-z0-9/+_=-]{32,100})[\\\"\\x27]',s):
