import pathlib,re,subprocess
root=pathlib.Path('.')
files=[]
for p in root.rglob('*'):
 if p.is_file() and '.git' not in p.parts:
  files.append(p)
replacements={}
patterns=[(r'(?:AKIA|ASIA)[A-Z0-9]{16}','<your-aws-access-key-id>'),(r'gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}','<your-github-token>'),(r'hf_[A-Za-z0-9]{20,}','<your-huggingface-token>')]
for p in files:
 try:s=p.read_text()
 except:continue
 for pattern,placeholder in patterns:
  for m in re.finditer(pattern,s):replacements[m.group()]=placeholder
 for pat in [r'AWS_SECRET_ACCESS_KEY\\s*=\\s*[\\\"\\x27]?([A-Za-z0-9/+=]{20,})',r'\\[\\\"AWS_SECRET_ACCESS_KEY\\\"\\]\\s*=\\s*\\\"(["'^'"\\\"]+)\\\"']:
  for m in re.finditer(pat,s):replacements[m.group(1)]='<your-aws-secret-access-key>'
for p in files:
 old=p.read_bytes();new=old
 for secret,placeholder in replacements.items():new=new.replace(secret.encode(),placeholder.encode())
 if old"'!=new:
  p.write_bytes(new);print('"'Sanitized',p)
print('Distinct credential values replaced:',len(replacements))
# Check all local Git objects without printing credential contents.
objects=subprocess.check_output(['git','cat-file','--batch-all-objects','--batch-check=%(objectname) %(objecttype)']).decode().splitlines()
counts={}
for row in objects:
 oid,kind=row.split()
 if kind not in ('blob','commit','tag'):continue
 data=subprocess.check_output(['git','cat-file',kind,oid])
 if any(secret.encode() in data for secret in replacements):counts[kind]=counts.get(kind,0)+1
print('Historical Git objects containing discovered values:',counts)
# Keep values in process memory only; full current-tree verification.
remaining=[]
for p in files:
 data=p.read_bytes()
 if any(secret.encode() in data for secret in replacements):remaining.append(str(p))
print('Working-tree files retaining discovered values:',remaining)
