for p in pathlib.Path('.').rglob('*'):
 if not p.is_file() or '.git' in p.parts:continue
 try:s=p.read_text()
 except:continue
 pat=r'(?:AKIA|ASIA)[A-Z0-9]{16}|gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|hf_[A-Za-z0-9]{20,}|sk-[A-Za-z0-9_-]{20,}|AIza[A-Za-z0-9_-]{30,}|xox[baprs]-[A-Za-z0-9-]+|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----'
 for m in re.finditer(pat,s):print('REMAINING CREDENTIAL PATTERN:',p,s.count('\\n',0,m.start())+1)
 for n,l in enumerate(s.splitlines(),1):
  if re.search(r'(?i)secret|api[_-]?key|access[_-]?key|auth[_-]?token|bearer|passwd|password|credential',l) and p.suffix not in ['.html','.jsonl']:
   # Report field names only, never values.
   fields=re.findall(r'(?i)[a-z_]*(?:secret|api_?key|access_?key|auth_?token|passwd|password|credential)[a-z_]*',l)
   print('Reviewed credential context:',p,n,','.join(sorted(set(fields))))
json.loads(pathlib.Path('exp_data/datasets/tokenized/rw_v2_fasttext_openhermes_vs_rw_v2_bigram_0.1_arcade100k.json').read_text())
ast.parse(pathlib.Path('ray_processing/process.py').read_text())
try:
 import yaml
 yaml.safe_load(pathlib.Path('ray_processing/ray_cluster.yaml').read_text())
